int countCollisions(char * directions){
    int n = 0;
    while(directions[n]) n++;

    // Skip all cars moving left from the left side (no collision possible)
    int left = 0;
    while(left < n && directions[left] == 'L') left++;

    // Skip all cars moving right from the right side (no collision possible)
    int right = n - 1;
    while(right >= 0 && directions[right] == 'R') right--;

    // Now consider the substring directions[left..right]
    // All cars here will eventually collide or become stationary.
    // Count how many cars are moving (L or R) in this range.
    int collisions = 0;
    for(int i = left; i <= right; i++){
        if(directions[i] != 'S') collisions++;
    }

    return collisions;
}

